########################################
# CI access for the platform/ingest GitHub Actions workflow
########################################

locals {
  github_repo = "platform/ingest"
  state_bucket = "ingest-terraform-state"
  state_key    = "ingest/terraform.tfstate"
}

data "aws_caller_identity" "current" {}

# One OIDC provider per account. If the account already has one for
# token.actions.githubusercontent.com, import it instead of creating it:
#   terraform import aws_iam_openid_connect_provider.github arn:aws:iam::<account>:oidc-provider/token.actions.githubusercontent.com
resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

# --- apply role: only assumable from the main branch ------------------------

data "aws_iam_policy_document" "ci_apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    # Exact match: pull_request runs and other branches cannot assume this role.
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:ref:refs/heads/main"]
    }
  }
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  assume_role_policy   = data.aws_iam_policy_document.ci_apply_trust.json
  max_session_duration = 3600
}

# --- plan role: pull requests, read-only on the managed resources -----------

data "aws_iam_policy_document" "ci_plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:pull_request"]
    }
  }
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  assume_role_policy   = data.aws_iam_policy_document.ci_plan_trust.json
  max_session_duration = 3600
}

# --- permissions -------------------------------------------------------------

locals {
  landing_bucket_arn = aws_s3_bucket.landing.arn
  queue_arn          = aws_sqs_queue.events.arn
  table_arn          = aws_dynamodb_table.checkpoints.arn
  state_bucket_arn   = "arn:aws:s3:::${local.state_bucket}"
}

# Read access to the state (and the S3 lockfile, which needs write on *.tflock).
data "aws_iam_policy_document" "state_read" {
  statement {
    sid       = "ListState"
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]
  }

  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = ["${local.state_bucket_arn}/${local.state_key}"]
  }

  statement {
    sid       = "StateLockfile"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${local.state_bucket_arn}/${local.state_key}.tflock"]
  }
}

data "aws_iam_policy_document" "state_write" {
  statement {
    sid       = "WriteState"
    actions   = ["s3:PutObject"]
    resources = ["${local.state_bucket_arn}/${local.state_key}"]
  }
}

data "aws_iam_policy_document" "managed_read" {
  statement {
    sid       = "ReadLandingBucket"
    actions   = ["s3:Get*", "s3:ListBucket"]
    resources = [local.landing_bucket_arn]
  }

  statement {
    sid       = "ReadQueue"
    actions   = ["sqs:GetQueueAttributes", "sqs:GetQueueUrl", "sqs:ListQueueTags"]
    resources = [local.queue_arn]
  }

  statement {
    sid = "ReadTable"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [local.table_arn]
  }
}

data "aws_iam_policy_document" "managed_write" {
  statement {
    sid       = "ManageLandingBucket"
    actions   = ["s3:*"]
    resources = [local.landing_bucket_arn, "${local.landing_bucket_arn}/*"]
  }

  statement {
    sid       = "ManageQueue"
    actions   = ["sqs:*"]
    resources = [local.queue_arn]
  }

  statement {
    sid       = "ManageTable"
    actions   = ["dynamodb:*"]
    resources = [local.table_arn]
  }

  # Creating (not just updating) these resources needs account-level calls that
  # cannot be scoped to an ARN that does not exist yet.
  statement {
    sid       = "CreateByName"
    actions   = ["s3:CreateBucket", "sqs:CreateQueue", "dynamodb:CreateTable"]
    resources = [
      "arn:aws:s3:::ingest-landing-staging",
      "arn:aws:sqs:eu-north-1:${data.aws_caller_identity.current.account_id}:ingest-events-staging",
      "arn:aws:dynamodb:eu-north-1:${data.aws_caller_identity.current.account_id}:table/ingest-checkpoints-staging",
    ]
  }
}

resource "aws_iam_role_policy" "ci_plan_state" {
  name   = "terraform-state-read"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.state_read.json
}

resource "aws_iam_role_policy" "ci_plan_managed" {
  name   = "managed-resources-read"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.managed_read.json
}

resource "aws_iam_role_policy" "ci_apply_state" {
  name   = "terraform-state"
  role   = aws_iam_role.ci_apply.id
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = concat(
      data.aws_iam_policy_document.state_read.statement_json_list,
      data.aws_iam_policy_document.state_write.statement_json_list,
    )
  })
}

resource "aws_iam_role_policy" "ci_apply_managed" {
  name   = "managed-resources"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.managed_write.json
}

output "ci_apply_role_arn" {
  value = aws_iam_role.ci_apply.arn
}

output "ci_plan_role_arn" {
  value = aws_iam_role.ci_plan.arn
}

